'use client'

import { ExternalLink, FileText } from 'lucide-react'
import { PageHeader } from '@/admin/components/layout/PageHeader'
import flows from '@/admin/lib/flow-docs.json'

// Step-by-step guides, one PDF per way of building (admin only, landing only, static website, web app
// and combinations). The PDFs are generated by docs/flows/build.py into public/docs/flows; this page
// lists them from the same generated flow-docs.json, so a new guide appears here after a rebuild.
export default function DocumentsPage() {
  return (
    <div className="max-w-4xl space-y-6">
      <PageHeader title="Documents" breadcrumbs={[{ label: 'Documents' }]} />
      <p className="text-sm text-muted-foreground">
        Step-by-step guides for every way of building with KDL OS. Pick the one that matches what
        you want to create. Each guide opens as a PDF in a new tab.
      </p>
      <ul className="grid gap-3 sm:grid-cols-2" aria-label="Flow guides">
        {flows.map((f) => (
          <li key={f.file}>
            <a
              href={`/docs/flows/${f.file}`}
              target="_blank"
              rel="noopener noreferrer"
              className="flex h-full items-start gap-3 rounded-lg border bg-card p-4 transition-colors hover:border-primary hover:bg-accent"
            >
              <FileText className="mt-0.5 h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-1.5 font-medium">
                  {f.title}
                  <ExternalLink className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
                  <span className="sr-only">(opens in a new tab)</span>
                </span>
                <span className="mt-1 block text-sm text-muted-foreground">{f.goal}</span>
              </span>
            </a>
          </li>
        ))}
      </ul>
    </div>
  )
}
